import type { PrismaClient, FilePurpose } from "@prisma/client";
import type { CreateFileRowData } from "../types";

const fileSelect = {
  id: true,
  remoteId: true,
  name: true,
  size: true,
  format: true,
  purpose: true,
  organizationId: true,
  uploadedById: true,
  createdAt: true,
  updatedAt: true,
} as const;

export class FileRepository {
  constructor(private readonly db: PrismaClient) {}

  async findById(id: string) {
    return this.db.file.findUnique({
      where: { id },
      select: fileSelect,
    });
  }

  async findByRemoteId(remoteId: string) {
    return this.db.file.findFirst({
      where: { remoteId },
      select: fileSelect,
    });
  }

  async findByPurpose(purpose: FilePurpose, organizationId: string) {
