    return row as TargetGroupUserView;
  }

  async deleteUser(id: string, targetGroupId: string): Promise<boolean> {
    const result = await this.db.targetGroupUser.deleteMany({
      where: { id, targetGroupId },
    });

    return result.count > 0;
  }
}

